CREATE TABLE `community_disaster_reduction_capacity` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `region_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区代码',
  `province_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省名称',
  `city_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市名称',
  `county_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '县名称',
  `township_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '乡镇名称',
  `community_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '社区（行政村）名称',
  `year` int NOT NULL COMMENT '数据所属年份',
  `has_emergency_plan` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '否' COMMENT '是否有社区（行政村）应急预案（是/否）',
  `has_vulnerable_groups_list` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '否' COMMENT '是否有本辖区弱势人群清单（是/否）',
  `has_disaster_points_list` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '否' COMMENT '是否有本辖区地质灾害等隐患点清单（是/否）',
  `has_disaster_map` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '否' COMMENT '是否有社区（行政村）灾害类地图（是/否）',
  `resident_population` int DEFAULT '0' COMMENT '常住人口数量（人）',
  `last_year_funding_amount` decimal(12,2) DEFAULT '0.00' COMMENT '上一年度防灾减灾救灾资金投入总金额（万元）',
  `materials_equipment_value` decimal(12,2) DEFAULT '0.00' COMMENT '现有储备物资、装备折合金额（万元）',
  `medical_service_count` int DEFAULT '0' COMMENT '社区医疗卫生服务站或村卫生室数量（个）',
  `militia_reserve_count` int DEFAULT '0' COMMENT '民兵预备役人数（人）',
  `registered_volunteer_count` int DEFAULT '0' COMMENT '登记注册志愿者人数（人）',
  `last_year_training_participants` int DEFAULT '0' COMMENT '上一年度防灾减灾培训活动培训人次（人次）',
  `last_year_drill_participants` int DEFAULT '0' COMMENT '参与上一年度组织的防灾减灾演练活动的居民(人次)',
  `emergency_shelter_capacity` int DEFAULT '0' COMMENT '本级灾害应急避难场所容量（人）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `unique_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '唯一码',
  `verification_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '核实状态',
  `community_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '社区（行政村）地址',
  `total_households` int DEFAULT NULL COMMENT '总户数（户）',
  `age_0_14_count` int DEFAULT NULL COMMENT '0-14岁人数',
  `age_65_plus_count` int DEFAULT NULL COMMENT '65岁（含）以上人数',
  `disabled_person_count` int DEFAULT NULL COMMENT '残障人员人数',
  `is_national_demo_community` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否为全国综合减灾示范社区（是/否）',
  `is_provincial_demo_community` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否为省级综合减灾示范社区（是/否）',
  `disaster_info_staff_count` int DEFAULT NULL COMMENT '灾害信息员人数（人）',
  `emergency_shelter_count` int DEFAULT NULL COMMENT '本级灾害应急避难场所数量（个或处）',
  `material_storage_method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '防灾减灾应急物资储备方式（多选）',
  `material_storage_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '防灾减灾应急物资储备方式-其他项说明',
  `warning_receive_method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾害预警信息接收方式（多选）',
  `warning_receive_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾害预警信息接收方式-其他项说明',
  `warning_communication_method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾害预警信息传达方式（多选）',
  `warning_communication_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾害预警信息传达方式-其他项说明',
  `disaster_report_method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾情信息上报方式（多选）',
  `disaster_report_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾情信息上报方式-其他项说明',
  `last_year_training_count` int DEFAULT NULL COMMENT '上一年度组织的防灾减灾培训活动次数（次）',
  `last_year_drill_count` int DEFAULT NULL COMMENT '上一年度组织的防灾减灾演练活动次数（次）',
  `unit_leader` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位负责人',
  `statistics_leader` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '统计负责人',
  `form_filler` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '填表人',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `report_date` date DEFAULT NULL COMMENT '报出日期（年/月/日）',
  `fill_instructions` text COLLATE utf8mb4_unicode_ci COMMENT '填写说明',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_community_region_community_year` (`region_code`,`community_name`,`year`),
  KEY `idx_region_code` (`region_code`),
  KEY `idx_province_name` (`province_name`),
  KEY `idx_city_name` (`city_name`),
  KEY `idx_county_name` (`county_name`),
  KEY `idx_township_name` (`township_name`),
  KEY `idx_year` (`year`),
  KEY `idx_community_unique_id` (`unique_id`),
  KEY `idx_community_year` (`year`)
) ENGINE=InnoDB AUTO_INCREMENT=468 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社区行政村减灾能力数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

