INSERT INTO `evaluation_model` VALUES (3,'乡镇减灾能力评估模型','STANDARD_MODEL','基于TOPSIS算法的标准减灾能力评估模型','1.0',1,1,'2025-10-12 09:43:09','2025-10-20 11:20:25',NULL,NULL),(4,'社区-行政村能力评估模型','COMMUNITY_CAPABILITY_MODEL','基于TOPSIS与分级的社区能力评估模型','1.0',1,0,'2025-10-16 02:10:43','2025-10-20 11:21:09',NULL,NULL),(8,'社区-乡镇能力评估模型','COMMUNITY_TOWNSHIP_AGGREGATION_MODEL','先对社区数据进行指标计算，然后按乡镇聚合求平均，再进行归一化和后续评估','1.0',1,0,'2025-10-16 10:56:42','2025-10-16 10:56:42',NULL,NULL),(11,'综合减灾能力评估模型','COMPREHENSIVE_EVALUATION_MODEL','整合标准模型和社区-乡镇模型的结果，通过新的权重体系计算综合评估结果','1.0',1,0,'2025-10-19 03:42:27','2025-10-19 03:42:27',NULL,NULL);
