DROP TABLE IF EXISTS `evaluation_result`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `evaluation_result` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Primary Key ID',
  `region_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Region Code',
  `region_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Region Name',
  `management_capability_score` decimal(15,8) DEFAULT NULL COMMENT 'Management Capability Score',
  `support_capability_score` decimal(15,8) DEFAULT NULL COMMENT 'Support Capability Score',
  `self_rescue_capability_score` decimal(15,8) DEFAULT NULL COMMENT 'Self Rescue Capability Score',
  `comprehensive_capability_score` decimal(15,8) DEFAULT NULL COMMENT 'Comprehensive Capability Score',
  `management_capability_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Management Capability Level',
  `support_capability_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Support Capability Level',
  `self_rescue_capability_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Self Rescue Capability Level',
  `comprehensive_capability_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Comprehensive Capability Level',
  `evaluation_model_id` bigint NOT NULL COMMENT 'Evaluation Model ID',
  `data_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Data Source (township/community)',
  `execution_record_id` bigint DEFAULT NULL COMMENT 'Execution Record ID',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Created By',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Create Time',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Updated By',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Update Time',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT 'Is Deleted (0-No, 1-Yes)',
  `org_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_region_code` (`region_code`),
