DROP TABLE IF EXISTS `firefighter_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `firefighter_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `region_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划代码',
  `province_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '省名称',
  `city_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '市名称',
  `county_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '县名称',
  `township_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '乡镇名称',
  `firefighter_count` int DEFAULT '0' COMMENT '消防员数量（人）',
  `status` tinyint DEFAULT '1' COMMENT '状态（1-启用，0-禁用）',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_region_code` (`region_code`) COMMENT '行政区划代码唯一约束',
  KEY `idx_location` (`province_name`,`city_name`,`county_name`,`township_name`) COMMENT '地理位置查询索引',
  KEY `idx_status` (`status`) COMMENT '状态索引'
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='消防员配置表';
