DROP TABLE IF EXISTS `organization`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `organization` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint DEFAULT NULL COMMENT '父级机构ID',
  `code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构编码（行政区划代码）',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构名称',
  `level` tinyint NOT NULL COMMENT '级别：1省、2市、3县、4乡镇、5社区',
  `data_source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源：COMMUNITY/TOWNSHIP 等',
  `province_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省名称',
  `city_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市名称',
  `county_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '县名称',
  `township_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '乡镇名称',
  `community_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '社区名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除 0-否 1-是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_organization_code` (`code`),
  KEY `idx_organization_parent` (`parent_id`),
  KEY `idx_organization_level` (`level`)
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='组织机构表';
/*!40101 SET character_set_client = @saved_cs_client */;

