INSERT INTO `step_algorithm` VALUES (634,15,'队伍管理能力计算','MANAGEMENT_CAPABILITY',1,'(management_staff * 1.0 / population) * 10000',NULL,'managementCapability','队伍管理能力=(本级灾害管理工作人员总数/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(635,15,'风险评估能力计算','RISK_ASSESSMENT_CAPABILITY',2,'risk_assessment != null && risk_assessment.equals(\"是\") ? 1.0 : 0.0',NULL,'riskAssessmentCapability','风险评估能力=IF(是否开展风险评估=\"是\",1,0)',1,'2025-10-19 09:19:04'),(636,15,'财政投入能力计算','FUNDING_CAPABILITY',3,'(funding_amount / population) * 10000',NULL,'fundingCapability','财政投入能力=(防灾减灾救灾资金投入总金额/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(637,15,'物资储备能力计算','MATERIAL_RESERVE_CAPABILITY',4,'(material_value / population) * 10000',NULL,'materialReserveCapability','物资储备能力=(物资储备价值/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(638,15,'医疗保障能力计算','MEDICAL_SUPPORT_CAPABILITY',5,'(hospital_beds / population) * 10000',NULL,'medicalSupportCapability','医疗保障能力=(实有住院床位数/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(639,15,'自救互救能力计算','SELF_RESCUE_CAPABILITY',6,'((firefighters + militia_reserve + volunteers) / population) * 10000',NULL,'selfRescueCapability','自救互救能力=((民兵预备役人数+志愿者人数)/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(640,15,'公众避险能力计算','PUBLIC_AVOIDANCE_CAPABILITY',7,'(training_participants / population) * 100',NULL,'publicAvoidanceCapability','公众避险能力=(应急管理培训和演练参与人次/常住人口数量)*100',1,'2025-10-19 09:19:04'),(641,15,'转移安置能力计算','RELOCATION_CAPABILITY',8,'(shelter_capacity / population) * 100',NULL,'relocationCapability','转移安置能力=(避难场所容量/常住人口数量)*100',1,'2025-10-19 09:19:04'),(642,16,'队伍管理能力归一化','MANAGEMENT_NORM',1,'@NORMALIZE:managementCapability',NULL,'managementCapabilityNorm','队伍管理能力归一化',1,'2025-10-19 09:19:04'),(643,16,'风险评估能力归一化','RISK_ASSESSMENT_NORM',2,'@NORMALIZE:riskAssessmentCapability',NULL,'riskAssessmentCapabilityNorm','风险评估能力归一化',1,'2025-10-19 09:19:04'),(644,16,'财政投入能力归一化','FUNDING_NORM',3,'@NORMALIZE:fundingCapability',NULL,'fundingCapabilityNorm','财政投入能力归一化',1,'2025-10-19 09:19:04'),(645,16,'物资储备能力归一化','MATERIAL_RESERVE_NORM',4,'@NORMALIZE:materialReserveCapability',NULL,'materialReserveCapabilityNorm','物资储备能力归一化',1,'2025-10-19 09:19:04'),(646,16,'医疗保障能力归一化','MEDICAL_SUPPORT_NORM',5,'@NORMALIZE:medicalSupportCapability',NULL,'medicalSupportCapabilityNorm','医疗保障能力归一化',1,'2025-10-19 09:19:04'),(647,16,'自救互救能力归一化','SELF_RESCUE_NORM',6,'@NORMALIZE:selfRescueCapability',NULL,'selfRescueCapabilityNorm','自救互救能力归一化',1,'2025-10-19 09:19:04'),(648,16,'公众避险能力归一化','PUBLIC_AVOIDANCE_NORM',7,'@NORMALIZE:publicAvoidanceCapability',NULL,'publicAvoidanceCapabilityNorm','公众避险能力归一化',1,'2025-10-19 09:19:04'),(649,16,'转移安置能力归一化','RELOCATION_NORM',8,'@NORMALIZE:relocationCapability',NULL,'relocationCapabilityNorm','转移安置能力归一化',1,'2025-10-19 09:19:04'),(650,17,'队伍管理能力定权','MANAGEMENT_WEIGHTED',1,'managementCapabilityNorm * 0.33 * 0.37',NULL,'managementCapabilityWeighted','队伍管理能力定权',1,'2025-10-19 09:19:05'),(651,17,'风险评估能力定权','RISK_ASSESSMENT_WEIGHTED',2,'riskAssessmentCapabilityNorm * 0.33 * 0.31',NULL,'riskAssessmentCapabilityWeighted','风险评估能力定权',1,'2025-10-19 09:19:05'),(652,17,'财政投入能力定权','FUNDING_WEIGHTED',3,'fundingCapabilityNorm * 0.33 * 0.32',NULL,'fundingCapabilityWeighted','财政投入能力定权',1,'2025-10-19 09:19:05'),(653,17,'物资储备能力定权','MATERIAL_RESERVE_WEIGHTED',4,'materialReserveCapabilityNorm  * 0.32 * 0.51',NULL,'materialReserveCapabilityWeighted','物资储备能力定权',1,'2025-10-19 09:19:05'),(654,17,'医疗保障能力定权','MEDICAL_SUPPORT_WEIGHTED',5,'medicalSupportCapabilityNorm  * 0.32 * 0.49',NULL,'medicalSupportCapabilityWeighted','医疗保障能力定权',1,'2025-10-19 09:19:05'),(655,17,'自救互救能力定权','SELF_RESCUE_WEIGHTED',6,'selfRescueCapabilityNorm * 0.35 * 0.33',NULL,'selfRescueCapabilityWeighted','自救互救能力定权',1,'2025-10-19 09:19:05'),(656,17,'公众避险能力定权','PUBLIC_AVOIDANCE_WEIGHTED',7,'publicAvoidanceCapabilityNorm * 0.35 * 0.33',NULL,'publicAvoidanceCapabilityWeighted','公众避险能力定权',1,'2025-10-19 09:19:05'),(657,17,'转移安置能力定权','RELOCATION_WEIGHTED',8,'relocationCapabilityNorm * 0.35 * 0.34',NULL,'relocationCapabilityWeighted','转移安置能力定权',1,'2025-10-19 09:19:05'),(803,17,'队伍管理能力二级定权','MANAGEMENT_SECONDARY',9,'managementCapabilityNorm * 0.37',NULL,'managementCapabilitySecondary','队伍管理能力二级定权（权重0.37）',1,'2025-10-21 03:49:29'),(804,17,'风险评估能力二级定权','RISK_ASSESSMENT_SECONDARY',10,'riskAssessmentCapabilityNorm * 0.31',NULL,'riskAssessmentCapabilitySecondary','风险评估能力二级定权（权重0.31）',1,'2025-10-21 03:49:29'),(805,17,'财政投入能力二级定权','FUNDING_SECONDARY',11,'fundingCapabilityNorm * 0.32',NULL,'fundingCapabilitySecondary','财政投入能力二级定权（权重0.32）',1,'2025-10-21 03:49:29'),(806,17,'物资储备能力二级定权','MATERIAL_RESERVE_SECONDARY',12,'materialReserveCapabilityNorm * 0.51',NULL,'materialReserveCapabilitySecondary','物资储备能力二级定权（权重0.51）',1,'2025-10-21 03:49:29'),(807,17,'医疗保障能力二级定权','MEDICAL_SUPPORT_SECONDARY',13,'medicalSupportCapabilityNorm * 0.49',NULL,'medicalSupportCapabilitySecondary','医疗保障能力二级定权（权重0.49）',1,'2025-10-21 03:49:29'),(808,17,'自救互救能力二级定权','SELF_RESCUE_SECONDARY',14,'selfRescueCapabilityNorm * 0.33',NULL,'selfRescueCapabilitySecondary','自救互救能力二级定权（权重0.33）',1,'2025-10-21 03:49:29'),(809,17,'公众避险能力二级定权','PUBLIC_AVOIDANCE_SECONDARY',15,'publicAvoidanceCapabilityNorm * 0.33',NULL,'publicAvoidanceCapabilitySecondary','公众避险能力二级定权（权重0.33）',1,'2025-10-21 03:49:29'),(810,17,'转移安置能力二级定权','RELOCATION_SECONDARY',16,'relocationCapabilityNorm * 0.34',NULL,'relocationCapabilitySecondary','转移安置能力二级定权（权重0.34）',1,'2025-10-21 03:49:29'),(811,18,'灾害管理能力优解','DISASTER_MGMT_POSITIVE',1,'@TOPSIS_POSITIVE:managementCapabilityWeighted,riskAssessmentCapabilityWeighted,fundingCapabilityWeighted',NULL,'disasterMgmtPositive','灾害管理能力维度优解（基于二级定权）',1,'2025-10-21 03:49:29'),(812,18,'灾害管理能力劣解','DISASTER_MGMT_NEGATIVE',2,'@TOPSIS_NEGATIVE:managementCapabilityWeighted,riskAssessmentCapabilityWeighted,fundingCapabilityWeighted',NULL,'disasterMgmtNegative','灾害管理能力维度劣解（基于二级定权）',1,'2025-10-21 03:49:29'),(813,18,'灾害备灾能力优解','DISASTER_PREP_POSITIVE',3,'@TOPSIS_POSITIVE:materialReserveCapabilityWeighted,medicalSupportCapabilityWeighted',NULL,'disasterPrepPositive','灾害备灾能力维度优解（基于二级定权）',1,'2025-10-21 03:49:29'),(814,18,'灾害备灾能力劣解','DISASTER_PREP_NEGATIVE',4,'@TOPSIS_NEGATIVE:materialReserveCapabilityWeighted,medicalSupportCapabilityWeighted',NULL,'disasterPrepNegative','灾害备灾能力维度劣解（基于二级定权）',1,'2025-10-21 03:49:29'),(815,18,'自救转移能力优解','SELF_RESCUE_POSITIVE',5,'@TOPSIS_POSITIVE:selfRescueCapabilityWeighted,publicAvoidanceCapabilityWeighted,relocationCapabilityWeighted',NULL,'selfRescuePositive','自救转移能力维度优解（基于二级定权）',1,'2025-10-21 03:49:29'),(816,18,'自救转移能力劣解','SELF_RESCUE_NEGATIVE',6,'@TOPSIS_NEGATIVE:selfRescueCapabilityWeighted,publicAvoidanceCapabilityWeighted,relocationCapabilityWeighted',NULL,'selfRescueNegative','自救转移能力维度劣解（基于二级定权）',1,'2025-10-21 03:49:29'),(817,18,'综合减灾能力优解','COMPREHENSIVE_POSITIVE',7,'@TOPSIS_POSITIVE:managementCapabilityWeighted,riskAssessmentCapabilityWeighted,fundingCapabilityWeighted,materialReserveCapabilityWeighted,medicalSupportCapabilityWeighted,selfRescueCapabilityWeighted,publicAvoidanceCapabilityWeighted,relocationCapabilityWeighted',NULL,'comprehensivePositive','综合减灾能力维度优解（基于一级定权）',1,'2025-10-21 03:49:29'),(818,18,'综合减灾能力劣解','COMPREHENSIVE_NEGATIVE',8,'@TOPSIS_NEGATIVE:managementCapabilityWeighted,riskAssessmentCapabilityWeighted,fundingCapabilityWeighted,materialReserveCapabilityWeighted,medicalSupportCapabilityWeighted,selfRescueCapabilityWeighted,publicAvoidanceCapabilityWeighted,relocationCapabilityWeighted',NULL,'comprehensiveNegative','综合减灾能力维度劣解（基于一级定权）',1,'2025-10-21 03:49:29'),(819,19,'灾害管理能力值','DISASTER_MGMT_SCORE',1,'disasterMgmtNegative / (disasterMgmtPositive + disasterMgmtNegative)',NULL,'management_capability_score','灾害管理能力值计算',1,'2025-10-21 03:49:29'),(820,19,'灾害备灾能力值','DISASTER_PREP_SCORE',2,'disasterPrepNegative / (disasterPrepPositive + disasterPrepNegative)',NULL,'support_capability_score','灾害备灾能力值计算',1,'2025-10-21 03:49:29'),(821,19,'自救转移能力值','SELF_RESCUE_SCORE',3,'selfRescueNegative / (selfRescuePositive + selfRescueNegative)',NULL,'self_rescue_capability_score','自救转移能力值计算',1,'2025-10-21 03:49:29'),(822,19,'综合减灾能力值','COMPREHENSIVE_SCORE',4,'comprehensiveNegative / (comprehensivePositive + comprehensiveNegative)',NULL,'comprehensive_capability_score','综合减灾能力值计算',1,'2025-10-21 03:49:29'),(823,19,'灾害管理能力分级','DISASTER_MGMT_GRADE',5,'@GRADE:management_capability_score',NULL,'management_capability_level','灾害管理能力分级',1,'2025-10-21 03:49:29'),(824,19,'灾害备灾能力分级','DISASTER_PREP_GRADE',6,'@GRADE:support_capability_score',NULL,'support_capability_level','灾害备灾能力分级',1,'2025-10-21 03:49:29'),(825,19,'自救转移能力分级','SELF_RESCUE_GRADE',7,'@GRADE:self_rescue_capability_score',NULL,'self_rescue_capability_level','自救转移能力分级',1,'2025-10-21 03:49:29'),(826,19,'综合减灾能力分级','COMPREHENSIVE_GRADE',8,'@GRADE:comprehensive_capability_score',NULL,'comprehensive_capability_level','综合减灾能力分级',1,'2025-10-21 03:49:29'),(1632,25,'财政投入能力赋值','FINANCIAL_INPUT',4,'(last_year_funding_amount == null ? 0.0 : last_year_funding_amount) / (resident_population == null || resident_population == 0 ? 1.0 : resident_population) * 10000',NULL,'FINANCIAL_INPUT','财政投入能力指标赋值算法',1,'2025-10-21 07:49:41'),(1633,25,'物资储备能力赋值','MATERIAL_RESERVE',5,'(materials_equipment_value == null ? 0.0 : materials_equipment_value) / (resident_population == null || resident_population == 0 ? 1.0 : resident_population) * 10000',NULL,'MATERIAL_RESERVE','物资储备能力指标赋值算法',1,'2025-10-21 07:49:41'),(1634,25,'医疗保障能力赋值','MEDICAL_SUPPORT',6,'(medical_service_count == null ? 0.0 : medical_service_count) / (resident_population == null || resident_population == 0 ? 1.0 : resident_population) * 10000',NULL,'MEDICAL_SUPPORT','医疗保障能力指标赋值算法',1,'2025-10-21 07:49:41'),(1635,25,'自救互救能力赋值','SELF_MUTUAL_AID',7,'((militia_reserve_count == null ? 0.0 : militia_reserve_count) + (registered_volunteer_count == null ? 0.0 : registered_volunteer_count)) / (resident_population == null || resident_population == 0 ? 1.0 : resident_population) * 10000',NULL,'SELF_MUTUAL_AID','自救互救能力指标赋值算法',1,'2025-10-21 07:49:41'),(1636,25,'公众疏散能力赋值','PUBLIC_EVACUATION',8,'