INSERT INTO `step_algorithm_copy1` VALUES (634,15,'队伍管理能力计算','MANAGEMENT_CAPABILITY',1,'(management_staff * 1.0 / population) * 10000',NULL,'managementCapability','队伍管理能力=(本级灾害管理工作人员总数/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(635,15,'风险评估能力计算','RISK_ASSESSMENT_CAPABILITY',2,'risk_assessment != null && risk_assessment.equals(\"是\") ? 1.0 : 0.0',NULL,'riskAssessmentCapability','风险评估能力=IF(是否开展风险评估=\"是\",1,0)',1,'2025-10-19 09:19:04'),(636,15,'财政投入能力计算','FUNDING_CAPABILITY',3,'(funding_amount / population) * 10000',NULL,'fundingCapability','财政投入能力=(防灾减灾救灾资金投入总金额/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(637,15,'物资储备能力计算','MATERIAL_RESERVE_CAPABILITY',4,'(material_value / population) * 10000',NULL,'materialReserveCapability','物资储备能力=(物资储备价值/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(638,15,'医疗保障能力计算','MEDICAL_SUPPORT_CAPABILITY',5,'(hospital_beds / population) * 10000',NULL,'medicalSupportCapability','医疗保障能力=(实有住院床位数/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(639,15,'自救互救能力计算','SELF_RESCUE_CAPABILITY',6,'((firefighters + militia_reserve + volunteers) / population) * 10000',NULL,'selfRescueCapability','自救互救能力=((民兵预备役人数+志愿者人数)/常住人口数量)*10000',1,'2025-10-19 09:19:04'),(640,15,'公众避险能力计算','PUBLIC_AVOIDANCE_CAPABILITY',7,'(training_participants / population) * 100',NULL,'publicAvoidanceCapability','公众避险能力=(应急管理培训和演练参与人次/常住人口数量)*100',1,'2025-10-19 09:19:04'),(641,15,'转移安置能力计算','RELOCATION_CAPABILITY',8,'(shelter_capacity / population) * 100',NULL,'relocationCapability','转移安置能力=(避难场所容量/常住人口数量)*100',1,'2025-10-19 09:19:04'),(642,16,'队伍管理能力归一化','MANAGEMENT_NORM',1,'@NORMALIZE:managementCapability',NULL,'managementCapabilityNorm','队伍管理能力归一化',1,'2025-10-19 09:19:04'),(643,16,'风险评估能力归一化','RISK_ASSESSMENT_NORM',2,'@NORMALIZE:riskAssessmentCapability',NULL,'riskAssessmentCapabilityNorm','风险评估能力归一化',1,'2025-10-19 09:19:04'),(644,16,'财政投入能力归一化','FUNDING_NORM',3,'@NORMALIZE:fundingCapability',NULL,'fundingCapabilityNorm','财政投入能力归一化',1,'2025-10-19 09:19:04'),(645,16,'物资储备能力归一化','MATERIAL_RESERVE