DROP TABLE IF EXISTS `survey_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `survey_data` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `unique_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '唯一码',
  `region_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区代码',
  `verification_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '核实状态',
  `province` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省名称',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市名称',
  `county` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '县名称',
  `township` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '乡镇名称',
  `township_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '乡镇（街道）地址',
  `year` int DEFAULT NULL COMMENT '数据所属年份',
  `population` bigint DEFAULT NULL COMMENT '常住人口数量',
  `total_households` int DEFAULT NULL COMMENT '年末总户数',
  `main_disaster_types` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '影响乡镇（街道）的主要灾害类型',
  `disaster_types_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '影响乡镇（街道）的主要灾害类型-其他项说明',
  `management_staff` int DEFAULT NULL COMMENT '本级灾害管理工作人员总数',
  `disaster_info_staff` int DEFAULT NULL COMMENT '本级灾害信息员人数',
  `risk_assessment` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否开展乡镇（街道）灾害风险评估',
  `has_disaster_map` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否有乡镇（街道）灾害类地图(是/否)',
  `warning_receive_method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾害预警信息接收方式',
  `warning_receive_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾害预警信息接收方式-其他项说明',
  `warning_communication_method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾害预警信息传达方式',
  `warning_communication_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾害预警信息传达方式-其他项说明',
  `disaster_report_method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾情信息上报方式',
  `disaster_report_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灾情信息上报方式-其他项说明',
  `emergency_plan_count` int DEFAULT NULL COMMENT '近3年编制或修订自然灾害应急预案数量(个)',
  `emergency_response_count` int DEFAULT NULL COMMENT '近3年针对自然灾害启动应急响应次数(次)',
  `training_drill_count` int DEFAULT NULL COMMENT '上一年度组织的应急管理培训和演练次数(次)',
  `funding_amount` decimal(15,2) DEFAULT NULL COMMENT '上一年度防灾减灾救灾资金投入总金额(万元)',
  `material_storage_method` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '救灾物资储备方式',
  `material_storage_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '救灾物资储备方式-其他项说明',
  `storage_point_count` int DEFAULT NULL COMMENT '本级救灾物资、装备储备点数量(个)',
  `storage_equipment_count` int DEFAULT NULL COMMENT '本级储备点救灾物资、装备数量(套/个/件)',
  `emergency_power_count` int DEFAULT NULL COMMENT '其中：应急电源或应急发电设备数量(套或件)',
  `emergency_communication_count` int DEFAULT NULL COMMENT '应急通信设备数量(套或件)',
  `emergency_water_count` int DEFAULT NULL COMMENT '应急供水设备数量(套或件)',
  `emergency_medical_count` int DEFAULT NULL COMMENT '应急医疗设备数量(套或件)',
  `material_value` decimal(15,2) DEFAULT NULL COMMENT '现有储备物资、装备折合金额(万元)',
  `shelter_count` int DEFAULT NULL COMMENT '本级灾害应急避难场所数量(个或处)',
  `hospital_beds` int DEFAULT '0',
  `firefighters` int DEFAULT '0',
  `volunteers` int DEFAULT '0',
  `militia_reserve` int DEFAULT '0',
  `training_participants` int DEFAULT NULL COMMENT '上一年度组织的应急管理培训和演练参与人次',
  `funding_support_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '乡镇（街道）综合减灾工作经费保障方式',
  `funding_support_method_other` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '乡镇（街道）综合减灾工作经费保障方式-其他说明',
  `shelter_capacity` int DEFAULT NULL COMMENT '本级灾害应急避难场所容量',
  `unit_leader` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位负责人',
  `statistics_leader` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '统计负责人',
  `form_filler` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '填表人',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `report_date` date DEFAULT NULL COMMENT '报出日期(年/月/日)',
  `fill_instructions` text COLLATE utf8mb4_unicode_ci COMMENT '填写说明',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` int DEFAULT '0',
  `volunteers_count` int DEFAULT '0' COMMENT '志愿者数量',
  PRIMARY KEY (`id`),
  KEY `idx_survey_data_region` (`region_code`),
  KEY `idx_survey_data_township` (`township`),
  KEY `idx_survey_data_create_time` (`create_time` DESC),
  KEY `idx_year` (`year`),
  KEY `idx_unique_id` (`unique_id`),
  KEY `idx_verification_status` (`verification_status`),
  KEY `idx_report_date` (`report_date`)
) ENGINE=InnoDB AUTO_INCREMENT=179 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
